import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Leads from './components/Leads';
import Pipeline from './components/Pipeline';
import Tasks from './components/Tasks';
import Meetings from './components/Meetings';
import Contacts from './components/Contacts';
import Accounts from './components/Accounts';
import Calls from './components/Calls';
import PlaceholderModule from './components/PlaceholderModule';
import AIChat from './components/AIChat';
import { MOCK_LEADS, MOCK_DEALS, MOCK_TASKS, MOCK_MEETINGS, MOCK_CONTACTS, MOCK_ACCOUNTS, MOCK_CALLS } from './constants';
import { IconMenu } from './components/Icons';
import { Lead, Deal, Activity, Task, Meeting, Contact, Account, Call } from './types';
import Notifications from './components/Notifications';

function App() {
  const [currentView, setCurrentView] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isDark, setIsDark] = useState(true);

  // State for data
  const [leads, setLeads] = useState<Lead[]>(MOCK_LEADS);
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);
  const [tasks] = useState<Task[]>(MOCK_TASKS);
  const [meetings] = useState<Meeting[]>(MOCK_MEETINGS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [accounts] = useState<Account[]>(MOCK_ACCOUNTS);
  const [calls, setCalls] = useState<Call[]>(MOCK_CALLS);

  // Pipeline Goal State with Persistence
  const [pipelineGoal, setPipelineGoal] = useState<number>(() => {
    const saved = localStorage.getItem('nova_pipeline_goal');
    return saved ? Number(saved) : 5000000; // Default 5M
  });

  const handleSetPipelineGoal = (goal: number) => {
    setPipelineGoal(goal);
    localStorage.setItem('nova_pipeline_goal', goal.toString());
  };

  const handleNavigateToTasks = () => {
    setCurrentView('tasks');
  };

  // Toggle Dark Mode Class on HTML element
  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  const toggleTheme = () => setIsDark(!isDark);

  const handleAddLead = (newLeadData: Omit<Lead, 'id'>) => {
    const leadToAdd: Lead = {
      ...newLeadData,
      id: `L${Date.now()}`,
      score: 50, // Default score
      scoreBreakdown: { fit: 50, engagement: 50, budget: 50 },
      notes: 'Newly created lead.',
      lastContact: new Date().toISOString().split('T')[0],
      name: `${newLeadData.firstName || ''} ${newLeadData.lastName || ''}`.trim(),
      owner: 'Bayas Ahamed',
    };
    setLeads(prevLeads => [leadToAdd, ...prevLeads]);
  };

  const handleUpdateLead = (updatedLead: Lead) => {
    setLeads(prevLeads => prevLeads.map(lead => 
      lead.id === updatedLead.id ? { ...lead, ...updatedLead, name: `${updatedLead.firstName || ''} ${updatedLead.lastName || ''}`.trim() } : lead
    ));
  };

  const handleDeleteLeads = (leadIdsToDelete: string[]) => {
    setLeads(prevLeads => prevLeads.filter(lead => !leadIdsToDelete.includes(lead.id)));
  };

  const handleAddContact = (contactData: Omit<Contact, 'id' | 'lastActivity'>) => {
    const newContact: Contact = {
      ...contactData,
      id: `C${Date.now()}`,
      lastActivity: 'Just now',
    };
    setContacts(prevContacts => [newContact, ...prevContacts]);
  };

  const handleUpdateContact = (updatedContact: Contact) => {
    setContacts(prevContacts => prevContacts.map(c => 
      c.id === updatedContact.id ? updatedContact : c
    ));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddDeal = (newDeal: Deal) => {
    const dealWithActivity = {
      ...newDeal,
      activities: [
        {
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }
      ]
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      // Check for Stage Change
      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({
          id: Date.now().toString() + 's',
          type: 'stage_change',
          description: `Stage updated to ${updatedDeal.stage}`,
          timestamp
        });
      }

      // Check for Value Change
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({
          id: Date.now().toString() + 'v',
          type: 'value_change',
          description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`,
          timestamp
        });
      }

      // Check for Probability Change
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({
          id: Date.now().toString() + 'p',
          type: 'probability_change',
          description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`,
          timestamp
        });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);

      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({
          id: Date.now().toString() + 'u',
          type: 'update',
          description: `Deal details updated`,
          timestamp
        });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
      case 'leads':
        return <Leads 
                  leads={leads} 
                  onAddLead={handleAddLead} 
                  onUpdateLead={handleUpdateLead} 
                  onDeleteLeads={handleDeleteLeads} 
               />;
      case 'pipeline':
        return <Pipeline deals={deals} onAddDeal={handleAddDeal} onUpdateDeal={handleUpdateDeal} pipelineGoal={pipelineGoal} onSetGoal={handleSetPipelineGoal} />;
      case 'tasks':
        return <Tasks tasks={tasks} />;
      case 'meetings':
        return <Meetings meetings={meetings} />;
      case 'contacts':
        return <Contacts contacts={contacts} onAddContact={handleAddContact} onUpdateContact={handleUpdateContact} />;
      case 'accounts':
        return <Accounts accounts={accounts} />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} onAddCall={handleAddCall} />;
      case 'campaigns':
        return <PlaceholderModule title="Campaigns" />;
      case 'documents':
        return <PlaceholderModule title="Documents" />;
      case 'visits':
        return <PlaceholderModule title="Visits" />;
      case 'projects':
        return <PlaceholderModule title="Projects" />;
      default:
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-purple-500/30 transition-colors duration-300">

      {/* Mobile Sidebar Overlay */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar Navigation */}
      <Sidebar 
        currentView={currentView} 
        setView={(view) => {
          setCurrentView(view);
          setSidebarOpen(false);
        }} 
        isOpen={sidebarOpen}
        isDark={isDark}
        toggleTheme={toggleTheme}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">

        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300">
          <div className="flex items-center">
            <button 
              onClick={() => setSidebarOpen(true)}
              className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white"
            >
              <IconMenu className="w-6 h-6" />
            </button>
            <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
          </div>
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </header>

        <div className="hidden md:block absolute top-6 right-8 z-20">
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </div>

        {/* Scrollable Content */}
        <main className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth">
          <div className="max-w-7xl mx-auto h-full">
            {renderContent()}
          </div>
        </main>
      </div>

      {/* Global AI Assistant */}
      <AIChat leads={leads} deals={deals} />
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { Contact } from '../types';
import { IconUsers, IconFilter, IconPhone, IconMail, IconX } from './Icons';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const initialFormState = {
  name: '',
  title: '',
  company: '',
  email: '',
  phone: '',
};

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState(initialFormState);
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleOpenModal = () => {
    setFormData(initialFormState);
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    setFormData({
      name: contact.name,
      title: contact.title,
      company: contact.company,
      email: contact.email,
      phone: contact.phone,
    });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.company) {
      alert('Name and Company are required.');
      return;
    }

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...formData
        });
      }
    } else {
      onAddContact(formData);
    }
    handleCloseModal();
  };

  return (
    <>
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Contacts</h1>
          <button 
            onClick={handleOpenModal}
            className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all"
          >
            + New Contact
          </button>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
          <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <IconFilter className="w-4 h-4 text-slate-400" />
              <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none">
                <option>All Contacts</option>
                <option>My Contacts</option>
              </select>
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                <th className="px-6 py-4 text-sm font-medium">Name</th>
                <th className="px-6 py-4 text-sm font-medium">Title</th>
                <th className="px-6 py-4 text-sm font-medium">Company</th>
                <th className="px-6 py-4 text-sm font-medium">Email</th>
                <th className="px-6 py-4 text-sm font-medium">Phone</th>
                <th className="px-6 py-4 text-sm font-medium">Last Activity</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {contacts.map((contact) => (
                <tr 
                  key={contact.id} 
                  onClick={() => handleEditClick(contact)}
                  className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer"
                >
                  <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                    <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center mr-3 text-sm font-bold text-slate-600 dark:text-slate-300">
                      {contact.name.charAt(0)}
                    </div>
                    {contact.name}
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{contact.title}</td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{contact.company}</td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300 flex items-center">
                    <IconMail className="w-3 h-3 mr-1.5 opacity-50" />
                    {contact.email}
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                    <div className="flex items-center">
                      <IconPhone className="w-3 h-3 mr-1.5 opacity-50" />
                      {contact.phone}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{contact.lastActivity}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white">
                {editingId ? 'Edit Contact' : 'Create New Contact'}
              </h2>
              <button onClick={handleCloseModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors">
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="overflow-y-auto p-6 space-y-4">
              <div>
                <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Full Name</label>
                <input type="text" name="name" required value={formData.name} onChange={handleInputChange} placeholder="e.g. John Doe" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Title</label>
                  <input type="text" name="title" value={formData.title} onChange={handleInputChange} placeholder="e.g. VP of Sales" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white" />
                </div>
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Company</label>
                  <input type="text" name="company" required value={formData.company} onChange={handleInputChange} placeholder="e.g. Acme Inc." className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white" />
                </div>
              </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Email</label>
                  <input type="email" name="email" value={formData.email} onChange={handleInputChange} placeholder="john.doe@acme.com" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white" />
                </div>
                 <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Phone</label>
                  <input type="tel" name="phone" value={formData.phone} onChange={handleInputChange} placeholder="555-123-4567" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white" />
                </div>
              </div>
              <div className="pt-4 flex space-x-3">
                <button type="button" onClick={handleCloseModal} className="flex-1 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                  Cancel
                </button>
                <button type="submit" className="flex-1 px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-colors">
                  {editingId ? 'Update Contact' : 'Save Contact'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

export default Contacts;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Call, Lead, Contact } from '../types';
import { summarizeCallNotes } from '../services/geminiService';
import { IconPhone, IconFilter, IconArrowUp, IconArrowDown, IconX, IconSparkles, IconSearch } from './Icons';

interface CallsProps {
  calls: Call[];
  leads: Lead[];
  contacts: Contact[];
  onAddCall: (callData: Omit<Call, 'id'>) => void;
}

const initialFormState: Omit<Call, 'id' | 'date'> = {
  subject: '',
  relatedTo: '',
  relatedToId: '',
  type: 'Outbound',
  outcome: 'Connected',
  notes: '',
  summary: ''
};

const Calls: React.FC<CallsProps> = ({ calls, leads, contacts, onAddCall }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newCallData, setNewCallData] = useState(initialFormState);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [sortConfig, setSortConfig] = useState<{ key: keyof Call; direction: 'asc' | 'desc' } | null>(null);

  // Searchable Dropdown State
  const [relatedToSearch, setRelatedToSearch] = useState('');
  const [isRelatedToDropdownOpen, setIsRelatedToDropdownOpen] = useState(false);
  const relatedToDropdownRef = useRef<HTMLDivElement>(null);

  // Click outside to close dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (relatedToDropdownRef.current && !relatedToDropdownRef.current.contains(event.target as Node)) {
        setIsRelatedToDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const sortedCalls = useMemo(() => {
    let sortableItems = [...calls];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [calls, sortConfig]);

  const requestSort = (key: keyof Call) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: keyof Call) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-4 h-4 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-4 h-4 text-purple-500" />;
    return <IconArrowDown className="w-4 h-4 text-purple-500" />;
  };

  const handleOpenModal = () => setIsModalOpen(true);
  const handleCloseModal = () => {
    setIsModalOpen(false);
    setNewCallData(initialFormState);
    setRelatedToSearch('');
    setIsSummarizing(false);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setNewCallData(prev => ({ ...prev, [name]: value }));
  };

  const handleGenerateSummary = async () => {
    if (!newCallData.notes) return;
    setIsSummarizing(true);
    const summary = await summarizeCallNotes(newCallData.notes);
    setNewCallData(prev => ({ ...prev, summary }));
    setIsSummarizing(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCallData.relatedToId) {
        alert("Please select a valid Lead or Contact for 'Related To'");
        return;
    }
    onAddCall({ ...newCallData, date: new Date().toISOString() });
    handleCloseModal();
  };

  const relatedToOptions = useMemo(() => {
    const leadOptions = leads.map(l => ({ id: l.id, name: l.name, type: 'Lead', label: `${l.name} (Lead)` }));
    const contactOptions = contacts.map(c => ({ id: c.id, name: c.name, type: 'Contact', label: `${c.name} (Contact)` }));
    return [...leadOptions, ...contactOptions];
  }, [leads, contacts]);

  const filteredRelatedOptions = useMemo(() => {
    if (!relatedToSearch) return relatedToOptions;
    return relatedToOptions.filter(opt => opt.label.toLowerCase().includes(relatedToSearch.toLowerCase()));
  }, [relatedToOptions, relatedToSearch]);

  const handleSelectRelatedTo = (option: { id: string, name: string, type: string, label: string }) => {
      setNewCallData(prev => ({ ...prev, relatedToId: option.id, relatedTo: option.label }));
      setRelatedToSearch(option.label);
      setIsRelatedToDropdownOpen(false);
  };

  return (
    <>
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Call Logs</h1>
          <button onClick={handleOpenModal} className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all">
            + New Call
          </button>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
          <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <IconFilter className="w-4 h-4 text-slate-400" />
              <span className="text-sm font-medium text-slate-700 dark:text-slate-300">All Calls</span>
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
              <tr>
                <th className="px-6 py-4"><button onClick={() => requestSort('subject')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Subject {getSortIcon('subject')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('relatedTo')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Related To {getSortIcon('relatedTo')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('type')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Call Type {getSortIcon('type')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('outcome')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Outcome {getSortIcon('outcome')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('date')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Date {getSortIcon('date')}</button></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {sortedCalls.map((call) => (
                <tr key={call.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                  <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center"><IconPhone className="w-4 h-4 mr-2 text-slate-400" />{call.subject}</td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{call.relatedTo}</td>
                  <td className="px-6 py-4"><span className={`px-2 py-1 text-sm font-medium rounded-full ${call.type === 'Inbound' ? 'bg-blue-100 text-blue-700 dark:bg-blue-500/10 dark:text-blue-400' : 'bg-purple-100 text-purple-700 dark:bg-purple-500/10 dark:text-purple-400'}`}>{call.type}</span></td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{call.outcome}</td>
                  <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{new Date(call.date).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Log a Call</h2>
              <button onClick={handleCloseModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
            </div>

            <form onSubmit={handleSubmit} className="overflow-y-auto p-6 space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Subject</label>
