                </div>

                {/* Searchable Select for Related To */}
                <div ref={relatedToDropdownRef} className="relative">
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Related To</label>
                  <div className="relative">
                    <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                        type="text" 
                        placeholder="Search leads or contacts..." 
                        value={relatedToSearch}
                        onChange={(e) => {
                            setRelatedToSearch(e.target.value);
                            setIsRelatedToDropdownOpen(true);
                        }}
                        onFocus={() => setIsRelatedToDropdownOpen(true)}
                        className="w-full pl-9 pr-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white placeholder-slate-400"
                    />
                  </div>
                  {isRelatedToDropdownOpen && (
                    <div className="absolute z-10 w-full mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-xl max-h-60 overflow-y-auto">
                        {filteredRelatedOptions.length > 0 ? (
                            filteredRelatedOptions.map(opt => (
                                <button
                                    key={`${opt.type}-${opt.id}`}
                                    type="button"
                                    onClick={() => handleSelectRelatedTo(opt)}
                                    className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors"
                                >
                                    <span className="font-medium">{opt.name}</span>
                                    <span className="ml-2 text-xs text-slate-500 dark:text-slate-400">({opt.type})</span>
                                </button>
                            ))
                        ) : (
                            <div className="px-4 py-2 text-sm text-slate-500 dark:text-slate-400">No results found.</div>
                        )}
                    </div>
                  )}
                  {/* Hidden input for HTML5 validation if needed, or check on submit */}
                  <input type="hidden" name="relatedToId" value={newCallData.relatedToId} required />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Call Type</label>
                  <select name="type" value={newCallData.type} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white">
                    <option>Outbound</option>
                    <option>Inbound</option>
                  </select>
                </div>
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Outcome</label>
                  <select name="outcome" value={newCallData.outcome} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white">
                    <option>Connected</option>
                    <option>Left Voicemail</option>
                    <option>No Answer</option>
                    <option>Scheduled Follow-up</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Notes</label>
                <textarea name="notes" value={newCallData.notes} onChange={handleInputChange} rows={5} placeholder="Enter details about the conversation..." className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"></textarea>
              </div>
              <div>
                <div className="flex justify-between items-center mb-1">
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300">AI Summary</label>
                  <button type="button" onClick={handleGenerateSummary} disabled={isSummarizing || !newCallData.notes} className="flex items-center px-3 py-1 text-xs font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-sm transition-colors disabled:opacity-50">
                    <IconSparkles className="w-3 h-3 mr-1.5" />
                    {isSummarizing ? 'Generating...' : 'Generate Summary'}
                  </button>
                </div>
                <textarea name="summary" value={newCallData.summary} readOnly={isSummarizing} onChange={handleInputChange} rows={3} placeholder={isSummarizing ? "AI is thinking..." : "AI-generated summary will appear here."} className="w-full px-3 py-2 bg-slate-100 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none text-slate-600 dark:text-slate-300"></textarea>
              </div>
              <div className="pt-4 flex space-x-3">
                <button type="button" onClick={handleCloseModal} className="flex-1 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-colors">Save Call</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

