import React, { useState } from 'react';
import { Contact } from '../types';
import { IconFilter, IconPhone, IconMail, IconX, IconUser, IconBuilding } from './Icons';
import ContactLayoutEditor from './ContactLayoutEditor';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const initialFormState: Partial<Contact> = {
  firstName: '',
  lastName: '',
  name: '',
  title: '',
  company: '', // Maps to 'Account Name'
  email: '',
  phone: '',
  otherPhone: '',
  mobile: '',
  assistant: '',
  reportingTo: '',
  leadSource: '-None-',
  department: '',
  homePhone: '',
  fax: '',
  dateOfBirth: '',
  asstPhone: '',
  emailOptOut: false
};

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Contact>>(initialFormState);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor onBack={() => setIsLayoutEditorOpen(false)} />;
  }

  const handleOpenModal = () => {
    setFormData(initialFormState);
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    // Split name if first/last not present
    const names = contact.name.split(' ');
    const derivedFirstName = contact.firstName || names[0] || '';
    const derivedLastName = contact.lastName || names.slice(1).join(' ') || '';

    setFormData({
      ...initialFormState,
      ...contact,
      firstName: derivedFirstName,
      lastName: derivedLastName,
      leadSource: contact.leadSource || '-None-',
      emailOptOut: contact.emailOptOut || false,
    });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    if (!formData.lastName || !formData.company) {
      alert('Last Name and Account Name are required.');
      return false;
    }

    const fullName = `${formData.firstName || ''} ${formData.lastName}`.trim();
    const contactData = {
      ...formData,
      name: fullName,
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData(initialFormState);
      setEditingId(null);
    }
  };

  return (
    <>
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Contacts</h1>
          <button 
            onClick={handleOpenModal}
            className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all"
          >
            + New Contact
          </button>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
          <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <IconFilter className="w-4 h-4 text-slate-400" />
              <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none">
                <option>All Contacts</option>
                <option>My Contacts</option>
              </select>
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                <th className="px-6 py-4 text-sm font-medium">Name</th>
                <th className="px-6 py-4 text-sm font-medium">Title</th>
                <th className="px-6 py-4 text-sm font-medium">Account Name</th>
                <th className="px-6 py-4 text-sm font-medium">Email</th>
                <th className="px-6 py-4 text-sm font-medium">Phone</th>
                <th className="px-6 py-4 text-sm font-medium">Last Activity</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {contacts.map((contact) => (
                <tr 
                  key={contact.id} 
                  onClick={() => handleEditClick(contact)}
                  className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer"
                >
                  <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                    <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center mr-3 text-sm font-bold text-slate-600 dark:text-slate-300">
                      {contact.name.charAt(0)}
                    </div>
                    {contact.name}
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{contact.title}</td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{contact.company}</td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300 flex items-center">
                    <IconMail className="w-3 h-3 mr-1.5 opacity-50" />
                    {contact.email}
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                    <div className="flex items-center">
                      <IconPhone className="w-3 h-3 mr-1.5 opacity-50" />
                      {contact.phone}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{contact.lastActivity}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-5xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            {/* Header */}
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50">
               <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                    {editingId ? 'Edit Contact' : 'Create Contact'}
                  </h2>
                  <button onClick={handleEditPageLayout} className="text-sm text-blue-600 hover:underline">Edit Page Layout</button>
               </div>
               <div className="flex items-center gap-2">
                 <button onClick={handleCloseModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                   Cancel
                 </button>
                 <button onClick={handleSaveAndNew} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                   Save and New
                 </button>
                 <button onClick={handleSubmit} className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded hover:bg-blue-500 transition-colors shadow-sm">
                   Save
                 </button>
               </div>
            </div>

            {/* Form Content */}
            <div className="overflow-y-auto p-6 md:p-8 bg-white dark:bg-slate-900">
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-x-12 gap-y-6">

                  {/* Left Column */}
                  <div className="space-y-5">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                      <label className="text-sm text-slate-600 dark:text-slate-400 md:text-right">Contact Owner</label>
                      <div className="md:col-span-2 relative">
                         <input type="text" value="Bayas Ahamed" readOnly className="w-full px-3 py-2 bg-slate-100 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded focus:outline-none text-slate-700 dark:text-slate-300 cursor-default" />
                         <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                      <label className="text-sm text-slate-600 dark:text-slate-400 md:text-right">First Name</label>
                      <div className="md:col-span-2 flex gap-2">
                        <select className="w-24 px-2 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white text-sm">
                          <option>-None-</option>
                          <option>Mr.</option>
                          <option>Ms.</option>
                          <option>Mrs.</option>
                          <option>Dr.</option>
                        </select>
                        <input type="text" name="firstName" value={formData.firstName} onChange={handleInputChange} className="flex-1 px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                      <label className="text-sm text-slate-600 dark:text-slate-400 md:text-right">Account Name</label>
                      <div className="md:col-span-2 relative">
                        <input type="text" name="company" value={formData.company} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white" />
                        <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                      <label className="text-sm text-slate-600 dark:text-slate-400 md:text-right">Email</label>
                      <div className="md:col-span-2">
                        <input type="email" name="email" value={formData.email} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                      <label className="text-sm text-slate-600 dark:text-slate-400 md:text-right">Phone</label>
                      <div className="md:col-span-2">
                        <input type="tel" name="phone" value={formData.phone} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                      <label className="text-sm text-slate-600 dark:text-slate-400 md:text-right">Other Phone</label>
                      <div className="md:col-span-2">
                        <input type="tel" name="otherPhone" value={formData.otherPhone} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white" />
                      </div>
                    </div>

