                         <input type="text" name="reportingTo" value={formData.reportingTo} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white" />
                         <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                      </div>
                    </div>
                  </div>

                  {/* Right Column */}
                  <div className="space-y-5">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                      <label className="text-sm text-slate-600 dark:text-slate-400 md:text-right">Lead Source</label>
                      <div className="md:col-span-2">
                        <select name="leadSource" value={formData.leadSource} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white">
                          <option>-None-</option>
                          <option>Advertisement</option>
                          <option>Cold Call</option>
                          <option>Employee Referral</option>
                          <option>External Referral</option>
