export default Contacts;

import React, { useState } from 'react';
import { Contact, ContactStatus } from '../types';
import { IconFilter, IconPhone, IconMail, IconX, IconUser, IconBuilding, IconList, IconKanban } from './Icons';
import ContactLayoutEditor from './ContactLayoutEditor';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const initialFormState: Partial<Contact> = {
  firstName: '',
  lastName: '',
  name: '',
  title: '',
  company: '', // Maps to 'Account Name'
  email: '',
  phone: '',
  otherPhone: '',
  mobile: '',
  assistant: '',
  reportingTo: '',
  leadSource: '-None-',
  department: '',
  homePhone: '',
  fax: '',
  dateOfBirth: '',
  asstPhone: '',
  emailOptOut: false,
  status: 'New'
};

const CONTACT_STATUSES: ContactStatus[] = ['New', 'Active', 'Inactive'];

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Contact>>(initialFormState);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);
  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor onBack={() => setIsLayoutEditorOpen(false)} />;
  }

  const handleOpenModal = () => {
    setFormData(initialFormState);
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    // Split name if first/last not present
    const names = contact.name.split(' ');
    const derivedFirstName = contact.firstName || names[0] || '';
    const derivedLastName = contact.lastName || names.slice(1).join(' ') || '';

    setFormData({
      ...initialFormState,
      ...contact,
      firstName: derivedFirstName,
      lastName: derivedLastName,
      leadSource: contact.leadSource || '-None-',
      emailOptOut: contact.emailOptOut || false,
      status: contact.status || 'New',
    });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    if (!formData.lastName || !formData.company) {
      alert('Last Name and Account Name are required.');
      return false;
    }

    const fullName = `${formData.firstName || ''} ${formData.lastName}`.trim();
    const contactData = {
      ...formData,
      name: fullName,
      status: formData.status || 'New',
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData(initialFormState);
      setEditingId(null);
    }
  };

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedContactId(id);
    e.dataTransfer.setData('contactId', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === id);

    if (contact && contact.status !== status) {
      onUpdateContact({ ...contact, status });
    }
    setDraggedContactId(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active': return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-300 dark:border-emerald-800';
      case 'Inactive': return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700';
      default: return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800';
    }
  };

  return (
    <>
      <div className="space-y-6 h-full flex flex-col">
        <div className="flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
             <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Contacts</h1>
             <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700">
                <button 
                  onClick={() => setViewMode('list')}
                  className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                  title="List View"
                >
                  <IconList className="w-4 h-4" />
                </button>
                <button 
                  onClick={() => setViewMode('kanban')}
                  className={`p-1.5 rounded-md transition-all ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                  title="Kanban View"
                >
                  <IconKanban className="w-4 h-4" />
                </button>
             </div>
          </div>
          <button 
            onClick={handleOpenModal}
            className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all"
          >
            + New Contact
          </button>
        </div>

        {viewMode === 'list' ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <IconFilter className="w-4 h-4 text-slate-400" />
                <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none">
                  <option>All Contacts</option>
                  <option>My Contacts</option>
                </select>
              </div>
            </div>
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                  <th className="px-6 py-4 text-sm font-medium">Name</th>
                  <th className="px-6 py-4 text-sm font-medium">Title</th>
                  <th className="px-6 py-4 text-sm font-medium">Account Name</th>
                  <th className="px-6 py-4 text-sm font-medium">Email</th>
                  <th className="px-6 py-4 text-sm font-medium">Phone</th>
                  <th className="px-6 py-4 text-sm font-medium">Status</th>
                  <th className="px-6 py-4 text-sm font-medium">Last Activity</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                {contacts.map((contact) => (
                  <tr 
                    key={contact.id} 
                    onClick={() => handleEditClick(contact)}
                    className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer"
                  >
                    <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                      <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center mr-3 text-sm font-bold text-slate-600 dark:text-slate-300">
                        {contact.name.charAt(0)}
                      </div>
                      {contact.name}
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{contact.title}</td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{contact.company}</td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300 flex items-center">
                      <IconMail className="w-3 h-3 mr-1.5 opacity-50" />
                      {contact.email}
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                      <div className="flex items-center">
                        <IconPhone className="w-3 h-3 mr-1.5 opacity-50" />
                        {contact.phone}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 text-xs font-semibold rounded-full border ${getStatusColor(contact.status || 'New')}`}>
                        {contact.status || 'New'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{contact.lastActivity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
