} from './Icons';

interface ContactLayoutEditorProps {
    onBack: () => void;
}

interface LayoutField {
    id: string;
    label: string;
    type: string;
    required: boolean;
    isLocked: boolean;
    value?: string;
    isComposite?: boolean; // For fields like First Name with salutation
}

const INITIAL_FIELDS: LayoutField[] = [
    { id: 'f1', label: 'Contact Owner', type: 'User', value: 'User', required: false, isLocked: true },
