    { id: 'f14', label: 'Date of Birth', type: 'Date', value: 'Date', required: false, isLocked: false },
    { id: 'f15', label: 'Assistant', type: 'Single Line', value: 'Single Line', required: false, isLocked: false },
    { id: 'f16', label: 'Asst Phone', type: 'Phone', value: 'Phone', required: false, isLocked: false },
];

const SidebarItem = ({ label, type }: { label: string, type: string }) => {
    const handleDragStart = (e: React.DragEvent) => {
        e.dataTransfer.setData('application/new-field', JSON.stringify({ label, type }));
        e.dataTransfer.effectAllowed = 'copy';
    };

    return (
        <div 
            draggable 
            onDragStart={handleDragStart}
            className="flex items-center px-3 py-2 bg-slate-800 border border-slate-700 rounded mb-2 cursor-grab hover:bg-slate-700 transition-colors active:cursor-grabbing"
        >
            <IconGripVertical className="w-4 h-4 text-slate-500 mr-2" />
            <span className="text-sm text-slate-300">{label}</span>
        </div>
    );
};

const ContactLayoutEditor: React.FC<ContactLayoutEditorProps> = ({ onBack }) => {
    const [fields, setFields] = useState<LayoutField[]>(INITIAL_FIELDS);
    const [activeFieldId, setActiveFieldId] = useState<string | null>(null);
    const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);

    // Close context menu when clicking outside
    React.useEffect(() => {
        const handleClickOutside = () => setActiveFieldId(null);
        window.addEventListener('click', handleClickOutside);
        return () => window.removeEventListener('click', handleClickOutside);
    }, []);

    const handleFieldClick = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        setActiveFieldId(activeFieldId === id ? null : id);
    };

    const handleRemoveField = (id: string) => {
        setFields(prev => prev.filter(f => f.id !== id));
        setActiveFieldId(null);
    };

    const handleToggleRequired = (id: string) => {
        setFields(prev => prev.map(f => f.id === id ? { ...f, required: !f.required } : f));
        setActiveFieldId(null); // Optional: keep menu open? decided to close
    };

    // Drag and Drop Handlers
    const handleDragStart = (e: React.DragEvent, index: number) => {
        e.dataTransfer.setData('application/field-index', index.toString());
        e.dataTransfer.effectAllowed = 'move';
        // Hide the context menu if dragging starts
        setActiveFieldId(null);
    };

    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        setDragOverIndex(index);
    };

    const handleDrop = (e: React.DragEvent, dropIndex: number) => {
        e.preventDefault();
        setDragOverIndex(null);

        const newFieldData = e.dataTransfer.getData('application/new-field');
        const draggedIndexStr = e.dataTransfer.getData('application/field-index');

        if (newFieldData) {
            // Adding a new field from sidebar
            const { label, type } = JSON.parse(newFieldData);
            const newField: LayoutField = {
                id: `new_${Date.now()}`,
                label,
                type,
                value: type,
                required: false,
                isLocked: false
            };

            setFields(prev => {
                const newFields = [...prev];
                newFields.splice(dropIndex, 0, newField);
                return newFields;
            });
        } else if (draggedIndexStr) {
            // Reordering existing field
            const draggedIndex = parseInt(draggedIndexStr, 10);
            if (draggedIndex === dropIndex) return;

            setFields(prev => {
                const newFields = [...prev];
                const [movedField] = newFields.splice(draggedIndex, 1);
                // Adjust drop index if dragging from above
                const adjustedDropIndex = draggedIndex < dropIndex ? dropIndex - 1 : dropIndex;
                newFields.splice(adjustedDropIndex, 0, movedField);
                return newFields;
            });
        }
    };

    const handleDropContainer = (e: React.DragEvent) => {
        e.preventDefault();
        // If dropped on the container but not a specific item, append to end
        if (e.target === e.currentTarget) {
             const newFieldData = e.dataTransfer.getData('application/new-field');
             if (newFieldData) {
