                                     </div>
                                 </div>

                                 <div className="grid grid-cols-2 gap-x-8 gap-y-4 px-2 pb-2">
                                     {fields.map((field, index) => (
                                         <div 
                                            key={field.id}
                                            draggable={!field.isLocked}
                                            onDragStart={(e) => handleDragStart(e, index)}
                                            onDragOver={(e) => handleDragOver(e, index)}
                                            onDrop={(e) => handleDrop(e, index)}
                                            className={`relative transition-all duration-200 ${dragOverIndex === index ? 'border-t-2 border-blue-500 pt-2' : ''}`}
                                         >
                                             <div 
                                                className={`relative p-3 border rounded-md group cursor-pointer transition-colors
                                                    ${activeFieldId === field.id ? 'bg-purple-50 border-purple-300 dark:bg-purple-900/20 dark:border-purple-500/50' : 'bg-white border-slate-200 dark:bg-slate-800 dark:border-slate-700 hover:border-purple-300 dark:hover:border-purple-500/50'}
                                                `}
                                                onClick={(e) => handleFieldClick(e, field.id)}
                                             >
                                                <div className="flex justify-between items-start mb-1 pointer-events-none">
                                                    <div className="flex items-center">
                                                        {field.required && <div className="w-1 h-4 bg-red-500 mr-2 rounded-full" title="Required"></div>}
                                                        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{field.label}</span>
                                                    </div>
                                                    <button className="opacity-0 group-hover:opacity-100 text-slate-400">
                                                        <IconSettings className="w-3 h-3" />
                                                    </button>
                                                </div>

                                                <div className="flex items-center justify-between pointer-events-none">
                                                    {field.isComposite ? (
                                                        <div className="flex gap-2 w-full">
                                                            <div className="w-1/3 border-r border-slate-200 dark:border-slate-600 pr-2">
                                                                <span className="text-xs text-slate-400">Salutation</span>
                                                            </div>
                                                            <div className="flex-1">
                                                                <span className="text-sm text-blue-600 dark:text-blue-400">{field.value}</span>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <>
                                                            <span className={`text-sm ${field.value ? 'text-blue-600 dark:text-blue-400' : 'text-slate-400'}`}>
                                                                {field.value || field.type}
                                                            </span>
                                                            {field.isLocked && <span className="text-xs text-slate-400">🔒</span>}
                                                        </>
                                                    )}
                                                </div>

                                                {/* Context Menu */}
                                                {activeFieldId === field.id && (
                                                    <div className="absolute top-full left-0 mt-1 w-48 bg-white dark:bg-slate-800 rounded-lg shadow-xl border border-slate-200 dark:border-slate-700 z-50 overflow-hidden animate-fade-in-down cursor-default">
                                                        <div className="py-1">
                                                            <button 
                                                                onClick={(e) => { e.stopPropagation(); handleToggleRequired(field.id); }}
                                                                className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center"
                                                            >
                                                                <IconCheckSquare className={`w-3 h-3 mr-2 ${field.required ? 'text-purple-500' : 'text-slate-400'}`} />
                                                                {field.required ? 'Unmark Required' : 'Mark as Required'}
                                                            </button>
                                                            {!field.isLocked && (
                                                                <>
                                                                    <div className="border-t border-slate-200 dark:border-slate-700 my-1"></div>
                                                                    <button 
                                                                        onClick={(e) => { e.stopPropagation(); handleRemoveField(field.id); }}
                                                                        className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center"
                                                                    >
                                                                        <IconTrash className="w-3 h-3 mr-2" />
                                                                        Remove Field
                                                                    </button>
                                                                </>
                                                            )}
                                                        </div>
                                                    </div>
                                                )}
                                             </div>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ContactLayoutEditor;

import React, { useState } from 'react';
import { Contact, ContactStatus, LayoutField } from '../types';
import { IconFilter, IconPhone, IconMail, IconX, IconUser, IconBuilding, IconList, IconKanban, IconInfo } from './Icons';
import ContactLayoutEditor from './ContactLayoutEditor';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const DEFAULT_LAYOUT: LayoutField[] = [
    { id: 'f1', label: 'Contact Owner', type: 'User', key: 'owner', value: 'User', required: false, isLocked: true },
    { id: 'f2', label: 'Lead Source', type: 'select', key: 'leadSource', value: 'Option 1', required: false, isLocked: false },
    { id: 'f3', label: 'First Name', type: 'text', key: 'firstName', value: 'Mr. ', required: false, isLocked: false, isComposite: true },
    { id: 'f4', label: 'Last Name', type: 'text', key: 'lastName', value: 'Single Line', required: true, isLocked: false },
    { id: 'f5', label: 'Account Name', type: 'text', key: 'company', value: 'Lookup', required: true, isLocked: false },
    { id: 'f6', label: 'Title', type: 'text', key: 'title', value: 'Single Line', required: false, isLocked: false },
    { id: 'f7', label: 'Email', type: 'email', key: 'email', value: 'Email', required: false, isLocked: false },
    { id: 'f8', label: 'Department', type: 'text', key: 'department', value: 'Single Line', required: false, isLocked: false },
    { id: 'f9', label: 'Phone', type: 'tel', key: 'phone', value: 'Phone', required: false, isLocked: false },
    { id: 'f10', label: 'Home Phone', type: 'tel', key: 'homePhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f11', label: 'Other Phone', type: 'tel', key: 'otherPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f12', label: 'Fax', type: 'tel', key: 'fax', value: 'Phone', required: false, isLocked: false },
    { id: 'f13', label: 'Mobile', type: 'tel', key: 'mobile', value: 'Phone', required: false, isLocked: false },
    { id: 'f14', label: 'Date of Birth', type: 'date', key: 'dateOfBirth', value: 'Date', required: false, isLocked: false },
    { id: 'f15', label: 'Assistant', type: 'text', key: 'assistant', value: 'Single Line', required: false, isLocked: false },
    { id: 'f16', label: 'Asst Phone', type: 'tel', key: 'asstPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f17', label: 'Email Opt Out', type: 'checkbox', key: 'emailOptOut', value: 'Check', required: false, isLocked: false },
    { id: 'f18', label: 'Status', type: 'select', key: 'status', value: 'New', required: true, isLocked: false }
];

const CONTACT_STATUSES: ContactStatus[] = ['New', 'Active', 'Inactive'];

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [layoutFields, setLayoutFields] = useState<LayoutField[]>(DEFAULT_LAYOUT);
  const [formData, setFormData] = useState<Partial<Contact>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);
  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor 
      currentLayout={layoutFields}
      onSave={(newLayout) => {
        setLayoutFields(newLayout);
        setIsLayoutEditorOpen(false);
      }}
      onBack={() => setIsLayoutEditorOpen(false)} 
    />;
  }

  const handleOpenModal = () => {
    setFormData({ status: 'New' }); // Default Values
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    setFormData({ ...contact });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    // Dynamic Validation based on Layout
    const missingFields = layoutFields.filter(field => field.required && !formData[field.key as keyof Contact] && field.key !== 'owner');

    if (missingFields.length > 0) {
      alert(`Please fill in the required fields: ${missingFields.map(f => f.label).join(', ')}`);
      return false;
    }

    // Name Construction logic
    let fullName = formData.name;
    if (!fullName) {
        const firstName = formData.firstName || '';
        const lastName = formData.lastName || '';
        fullName = `${firstName} ${lastName}`.trim();
        if (!fullName && formData.company) fullName = formData.company; // Fallback
    }

    const contactData = {
      ...formData,
      name: fullName || 'Unknown',
      status: formData.status || 'New',
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData({ status: 'New' });
      setEditingId(null);
    }
  };

  // Drag and Drop Handlers (Kanban)
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedContactId(id);
    e.dataTransfer.setData('contactId', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === id);

    if (contact && contact.status !== status) {
      onUpdateContact({ ...contact, status });
    }
    setDraggedContactId(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active': return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-300 dark:border-emerald-800';
      case 'Inactive': return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700';
      default: return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800';
    }
  };

  const renderField = (field: LayoutField) => {
      const isRequired = field.required;
      const commonClasses = `w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border ${isRequired && !formData[field.key as keyof Contact] ? 'border-red-300 dark:border-red-800' : 'border-slate-200 dark:border-slate-700'} rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white`;

      if (field.key === 'owner') {
          return (
            <div className="relative">
                <input type="text" value="Bayas Ahamed" readOnly className={`${commonClasses} cursor-default`} />
                <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            </div>
          );
      }

      if (field.isComposite && field.key === 'firstName') {
          return (
            <div className="flex gap-2">
                <select className="w-24 px-2 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white text-sm">
                    <option>Mr.</option>
                    <option>Ms.</option>
                    <option>Dr.</option>
                </select>
                <input 
                    type="text" 
                    name={field.key} 
                    value={formData[field.key as keyof Contact] || ''} 
                    onChange={handleInputChange} 
                    className={commonClasses} 
                />
            </div>
          );
      }

      switch (field.type) {
          case 'select':
              return (
                  <select name={field.key} value={formData[field.key as keyof Contact] || ''} onChange={handleInputChange} className={commonClasses}>
                      {field.key === 'status' ? CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>) : (
                          <>
                            <option value="">-None-</option>
                            <option value="Option 1">Option 1</option>
                            <option value="Option 2">Option 2</option>
                          </>
                      )}
                  </select>
              );
          case 'checkbox':
              return (
                  <div className="flex items-center h-full">
                      <input type="checkbox" name={field.key} checked={!!formData[field.key as keyof Contact]} onChange={handleInputChange} className="w-4 h-4 text-blue-600 bg-slate-100 border-slate-300 rounded focus:ring-blue-500 dark:focus:ring-blue-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600" />
                  </div>
              );
          default:
              return (
                  <div className="relative">
                    <input 
                        type={field.type} 
                        name={field.key} 
                        value={formData[field.key as keyof Contact] || ''} 
                        onChange={handleInputChange} 
                        className={commonClasses} 
                    />
                    {field.key === 'company' && <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />}
                  </div>
              );
      }
  };

  return (
    <>
      <div className="space-y-6 h-full flex flex-col">
        {/* Header and Kanban/List Toggle - Same as before */}
        <div className="flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
             <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Contacts</h1>
             <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700">
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}><IconList className="w-4 h-4" /></button>
                <button onClick={() => setViewMode('kanban')} className={`p-1.5 rounded-md transition-all ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}><IconKanban className="w-4 h-4" /></button>
             </div>
          </div>
          <button onClick={handleOpenModal} className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all">+ New Contact</button>
        </div>

        {/* Views Render (List or Kanban) - Same as before */}
        {viewMode === 'list' ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <div className="flex items-center space-x-2"><IconFilter className="w-4 h-4 text-slate-400" /><select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none"><option>All Contacts</option></select></div>
            </div>
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                  <th className="px-6 py-4 font-medium">Name</th>
                  <th className="px-6 py-4 font-medium">Title</th>
                  <th className="px-6 py-4 font-medium">Account Name</th>
                  <th className="px-6 py-4 font-medium">Email</th>
                  <th className="px-6 py-4 font-medium">Phone</th>
                  <th className="px-6 py-4 font-medium">Status</th>
                  <th className="px-6 py-4 font-medium">Last Activity</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                {contacts.map((contact) => (
                  <tr key={contact.id} onClick={() => handleEditClick(contact)} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer">
                    <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center"><div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center mr-3 text-sm font-bold text-slate-600 dark:text-slate-300">{contact.name.charAt(0)}</div>{contact.name}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.title}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.company}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300 flex items-center"><IconMail className="w-3 h-3 mr-1.5 opacity-50" />{contact.email}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300"><div className="flex items-center"><IconPhone className="w-3 h-3 mr-1.5 opacity-50" />{contact.phone}</div></td>
                    <td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-semibold rounded-full border ${getStatusColor(contact.status || 'New')}`}>{contact.status || 'New'}</span></td>
                    <td className="px-6 py-4 text-slate-500 dark:text-slate-400">{contact.lastActivity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
            <div className="flex h-full gap-6 min-w-full">
              {CONTACT_STATUSES.map(status => (
                <div key={status} onDragOver={handleDragOver} onDrop={(e) => handleDrop(e, status)} className="flex-1 min-w-[320px] flex flex-col bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl h-full">
                  <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-white/50 dark:bg-slate-800/50 rounded-t-xl backdrop-blur-sm sticky top-0 z-10">
                    <h3 className="font-semibold text-slate-700 dark:text-slate-200 flex items-center gap-2"><span className={`w-2.5 h-2.5 rounded-full ${status === 'Active' ? 'bg-emerald-500' : status === 'Inactive' ? 'bg-slate-400' : 'bg-blue-500'}`}></span>{status}</h3>
                    <span className="bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold px-2 py-0.5 rounded-full">{contacts.filter(c => (c.status || 'New') === status).length}</span>
                  </div>
                  <div className="p-4 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                     {contacts.filter(c => (c.status || 'New') === status).map(contact => (
                       <div key={contact.id} draggable onDragStart={(e) => handleDragStart(e, contact.id)} onClick={() => handleEditClick(contact)} className={`p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm hover:shadow-md transition-all cursor-move group select-none ${draggedContactId === contact.id ? 'opacity-50 border-dashed border-slate-400' : 'hover:border-purple-400 dark:hover:border-purple-500/50'}`}>
                         <div className="flex items-start justify-between mb-2">
                           <div className="flex items-center"><div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 mr-2 border border-slate-200 dark:border-slate-600">{contact.name.charAt(0)}</div><div><h4 className="font-semibold text-slate-800 dark:text-slate-100 text-sm">{contact.name}</h4><p className="text-xs text-slate-500 dark:text-slate-400">{contact.title}</p></div></div>
                         </div>
                         <div className="mb-3 pl-10"><p className="text-sm text-slate-600 dark:text-slate-300 flex items-center mb-1"><IconBuilding className="w-3 h-3 mr-1.5 text-slate-400" />{contact.company}</p>{(contact.email || contact.phone) && (<div className="flex items-center gap-3 text-xs text-slate-500 dark:text-slate-400 mt-2">{contact.email && <span className="flex items-center gap-1"><IconMail className="w-3 h-3" /> Email</span>}{contact.phone && <span className="flex items-center gap-1"><IconPhone className="w-3 h-3" /> Call</span>}</div>)}</div>
                         <div className="flex justify-between items-center pt-2 border-t border-slate-100 dark:border-slate-700/50 pl-10"><span className="text-xs text-slate-400">{contact.lastActivity}</span></div>
                       </div>
                     ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-5xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            {/* Header */}
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50">
               <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                    {editingId ? 'Edit Contact' : 'Create Contact'}
                  </h2>
                  <button onClick={handleEditPageLayout} className="text-sm text-blue-600 hover:underline">Edit Page Layout</button>
               </div>
               <div className="flex items-center gap-2">
                 <button onClick={handleCloseModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                 <button onClick={handleSaveAndNew} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Save and New</button>
                 <button onClick={handleSubmit} className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded hover:bg-blue-500 transition-colors shadow-sm">Save</button>
               </div>
            </div>

            {/* Dynamic Form Content */}
            <div className="overflow-y-auto p-6 md:p-8 bg-white dark:bg-slate-900">
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                    {layoutFields.map((field) => (
                        <div key={field.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                            <label className={`text-sm text-slate-600 dark:text-slate-400 md:text-right ${field.required ? 'border-l-2 border-red-500 pl-2 md:border-l-0 md:pl-0 md:after:content-["*"] md:after:text-red-500 md:after:ml-1' : ''}`}>
                                {field.label}
                            </label>
                            <div className="md:col-span-2">
                                {renderField(field)}
                            </div>
                        </div>
                    ))}
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Contacts;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Leads from './components/Leads';
import Pipeline from './components/Pipeline';
import Tasks from './components/Tasks';
import Meetings from './components/Meetings';
import Contacts from './components/Contacts';
import Accounts from './components/Accounts';
import Calls from './components/Calls';
import PlaceholderModule from './components/PlaceholderModule';
import AIChat from './components/AIChat';
import { MOCK_LEADS, MOCK_DEALS, MOCK_TASKS, MOCK_MEETINGS, MOCK_CONTACTS, MOCK_ACCOUNTS, MOCK_CALLS } from './constants';
import { IconMenu } from './components/Icons';
import { Lead, Deal, Activity, Task, Meeting, Contact, Account, Call } from './types';
import Notifications from './components/Notifications';

function App() {
  const [currentView, setCurrentView] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isDark, setIsDark] = useState(true);

  // State for data
  const [leads, setLeads] = useState<Lead[]>(MOCK_LEADS);
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);
  const [tasks] = useState<Task[]>(MOCK_TASKS);
  const [meetings] = useState<Meeting[]>(MOCK_MEETINGS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [accounts] = useState<Account[]>(MOCK_ACCOUNTS);
  const [calls, setCalls] = useState<Call[]>(MOCK_CALLS);

  // Pipeline Goal State with Persistence
  const [pipelineGoal, setPipelineGoal] = useState<number>(() => {
    const saved = localStorage.getItem('nova_pipeline_goal');
    return saved ? Number(saved) : 5000000; // Default 5M
  });

  const handleSetPipelineGoal = (goal: number) => {
    setPipelineGoal(goal);
    localStorage.setItem('nova_pipeline_goal', goal.toString());
  };

  const handleNavigateToTasks = () => {
    setCurrentView('tasks');
  };

  // Toggle Dark Mode Class on HTML element
  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  const toggleTheme = () => setIsDark(!isDark);

  const handleAddLead = (newLeadData: Omit<Lead, 'id'>) => {
    const leadToAdd: Lead = {
      ...newLeadData,
      id: `L${Date.now()}`,
      score: 50, // Default score
      scoreBreakdown: { fit: 50, engagement: 50, budget: 50 },
      notes: 'Newly created lead.',
      lastContact: new Date().toISOString().split('T')[0],
      name: `${newLeadData.firstName || ''} ${newLeadData.lastName || ''}`.trim(),
      owner: 'Bayas Ahamed',
    };
    setLeads(prevLeads => [leadToAdd, ...prevLeads]);
  };

  const handleUpdateLead = (updatedLead: Lead) => {
    setLeads(prevLeads => prevLeads.map(lead => 
      lead.id === updatedLead.id ? { ...lead, ...updatedLead, name: `${updatedLead.firstName || ''} ${updatedLead.lastName || ''}`.trim() } : lead
    ));
  };

  const handleDeleteLeads = (leadIdsToDelete: string[]) => {
    setLeads(prevLeads => prevLeads.filter(lead => !leadIdsToDelete.includes(lead.id)));
  };

  const handleAddContact = (contactData: Omit<Contact, 'id' | 'lastActivity'>) => {
    const newContact: Contact = {
      ...contactData,
      id: `C${Date.now()}`,
      lastActivity: 'Just now',
    } as Contact;
    setContacts(prevContacts => [newContact, ...prevContacts]);
  };

  const handleUpdateContact = (updatedContact: Contact) => {
    setContacts(prevContacts => prevContacts.map(c => 
      c.id === updatedContact.id ? updatedContact : c
    ));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddDeal = (newDeal: Deal) => {
    const dealWithActivity = {
      ...newDeal,
      activities: [
        {
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }
      ]
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      // Check for Stage Change
      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({
          id: Date.now().toString() + 's',
          type: 'stage_change',
          description: `Stage updated to ${updatedDeal.stage}`,
          timestamp
        });
      }

      // Check for Value Change
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({
          id: Date.now().toString() + 'v',
          type: 'value_change',
          description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`,
          timestamp
        });
      }

      // Check for Probability Change
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({
          id: Date.now().toString() + 'p',
          type: 'probability_change',
          description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`,
          timestamp
        });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);

      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({
          id: Date.now().toString() + 'u',
          type: 'update',
          description: `Deal details updated`,
          timestamp
        });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
      case 'leads':
        return <Leads 
                  leads={leads} 
                  onAddLead={handleAddLead} 
                  onUpdateLead={handleUpdateLead} 
                  onDeleteLeads={handleDeleteLeads} 
               />;
      case 'pipeline':
        return <Pipeline deals={deals} onAddDeal={handleAddDeal} onUpdateDeal={handleUpdateDeal} pipelineGoal={pipelineGoal} onSetGoal={handleSetPipelineGoal} />;
      case 'tasks':
        return <Tasks tasks={tasks} />;
      case 'meetings':
        return <Meetings meetings={meetings} />;
      case 'contacts':
        return <Contacts contacts={contacts} onAddContact={handleAddContact} onUpdateContact={handleUpdateContact} />;
      case 'accounts':
        return <Accounts accounts={accounts} />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} onAddCall={handleAddCall} />;
      case 'campaigns':
        return <PlaceholderModule title="Campaigns" />;
      case 'documents':
        return <PlaceholderModule title="Documents" />;
      case 'visits':
        return <PlaceholderModule title="Visits" />;
      case 'projects':
        return <PlaceholderModule title="Projects" />;
      default:
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-purple-500/30 transition-colors duration-300">

      {/* Mobile Sidebar Overlay */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar Navigation */}
      <Sidebar 
        currentView={currentView} 
        setView={(view) => {
          setCurrentView(view);
          setSidebarOpen(false);
        }} 
        isOpen={sidebarOpen}
        isDark={isDark}
        toggleTheme={toggleTheme}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">

        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300">
          <div className="flex items-center">
            <button 
              onClick={() => setSidebarOpen(true)}
              className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white"
            >
              <IconMenu className="w-6 h-6" />
            </button>
            <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
          </div>
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </header>

        <div className="hidden md:block absolute top-6 right-8 z-20">
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </div>

        {/* Scrollable Content */}
        <main className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth">
          <div className="max-w-7xl mx-auto h-full">
            {renderContent()}
          </div>
        </main>
      </div>

      {/* Global AI Assistant */}
      <AIChat leads={leads} deals={deals} />
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { LayoutField } from '../types';
import { 
    IconArrowLeft, 
    IconSettings, 
    IconGripVertical, 
    IconChevronDown, 
    IconChevronRight, 
    IconUser, 
    IconToggleLeft,
    IconPlus,
    IconTrash,
    IconCheckSquare
} from './Icons';

interface ContactLayoutEditorProps {
    currentLayout: LayoutField[];
    onSave: (layout: LayoutField[]) => void;
    onBack: () => void;
}

const SidebarItem = ({ label, type }: { label: string, type: string }) => {
    const handleDragStart = (e: React.DragEvent) => {
        // Create a template for the new field. 
        // We generate a temporary ID/Key here, but the drop handler should regenerate them to ensure uniqueness on every drop.
        const fieldKey = `custom_${type.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${Date.now()}`;
        const newFieldData: LayoutField = {
            id: `new_template_${Date.now()}`, 
            label: label,
            type: type,
            key: fieldKey,
            required: false,
            isLocked: false,
            value: `[${label}]`
        };
        e.dataTransfer.setData('application/new-field', JSON.stringify(newFieldData));
        e.dataTransfer.effectAllowed = 'copy';
    };

    return (
        <div 
            draggable 
            onDragStart={handleDragStart}
            className="flex items-center px-3 py-2 bg-slate-800 border border-slate-700 rounded mb-2 cursor-grab hover:bg-slate-700 transition-colors active:cursor-grabbing"
        >
            <IconGripVertical className="w-4 h-4 text-slate-500 mr-2" />
            <span className="text-sm text-slate-300">{label}</span>
        </div>
    );
};

const ContactLayoutEditor: React.FC<ContactLayoutEditorProps> = ({ currentLayout, onSave, onBack }) => {
    const [fields, setFields] = useState<LayoutField[]>(currentLayout);
    const [activeFieldId, setActiveFieldId] = useState<string | null>(null);
    const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);

    // Close context menu when clicking outside
    React.useEffect(() => {
        const handleClickOutside = () => setActiveFieldId(null);
        window.addEventListener('click', handleClickOutside);
        return () => window.removeEventListener('click', handleClickOutside);
    }, []);

    const handleFieldClick = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        setActiveFieldId(activeFieldId === id ? null : id);
    };

    const handleRemoveField = (id: string) => {
        setFields(prev => prev.filter(f => f.id !== id));
        setActiveFieldId(null);
    };

    const handleToggleRequired = (id: string) => {
        setFields(prev => prev.map(f => f.id === id ? { ...f, required: !f.required } : f));
        setActiveFieldId(null);
    };

    const handleSaveLayout = () => {
        onSave(fields);
    };

    // Drag and Drop Handlers
    const handleDragStart = (e: React.DragEvent, index: number) => {
        e.dataTransfer.setData('application/field-index', index.toString());
        e.dataTransfer.effectAllowed = 'move';
        setActiveFieldId(null);
    };

    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault(); // Necessary to allow dropping
        e.dataTransfer.dropEffect = 'move';
        setDragOverIndex(index);
    };

    const handleContainerDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
    };

    // Helper to create a unique field from template
    const createFieldFromTemplate = (template: LayoutField): LayoutField => {
        const timestamp = Date.now();
        const randomStr = Math.random().toString(36).substring(2, 9);
        return {
            ...template,
            id: `field_${timestamp}_${randomStr}`,
            key: `custom_${template.type}_${timestamp}_${randomStr}`,
        };
    };

    const handleDrop = (e: React.DragEvent, dropIndex: number) => {
        e.preventDefault();
        e.stopPropagation(); // Stop bubbling to container
        setDragOverIndex(null);

        const newFieldJson = e.dataTransfer.getData('application/new-field');
        const draggedIndexStr = e.dataTransfer.getData('application/field-index');

        if (newFieldJson) {
            // Adding a new field from sidebar
            try {
                const template = JSON.parse(newFieldJson) as LayoutField;
                const newField = createFieldFromTemplate(template);

                setFields(prev => {
                    const newFields = [...prev];
                    newFields.splice(dropIndex, 0, newField);
                    return newFields;
                });
            } catch (err) {
                console.error("Error parsing new field data:", err);
            }
        } else if (draggedIndexStr) {
            // Reordering existing field
            const draggedIndex = parseInt(draggedIndexStr, 10);
            if (draggedIndex === dropIndex) return;

            setFields(prev => {
                const newFields = [...prev];
                const [movedField] = newFields.splice(draggedIndex, 1);
                // Adjust drop index if dragging from above
                const adjustedDropIndex = draggedIndex < dropIndex ? dropIndex - 1 : dropIndex;
                newFields.splice(adjustedDropIndex, 0, movedField);
                return newFields;
            });
        }
    };

    const handleDropContainer = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation(); // Ensure we handle it here if it bubbled up (though standard drag events might not bubble same way)

        const newFieldJson = e.dataTransfer.getData('application/new-field');
        const draggedIndexStr = e.dataTransfer.getData('application/field-index');

        if (newFieldJson) {
             try {
                const template = JSON.parse(newFieldJson) as LayoutField;
                const newField = createFieldFromTemplate(template);
                setFields(prev => [...prev, newField]);
             } catch (err) {
                 console.error("Error parsing new field data:", err);
             }
        } else if (draggedIndexStr) {
             // If dragging an existing field to the container background (effectively moving to end)
             const draggedIndex = parseInt(draggedIndexStr, 10);
             if (!isNaN(draggedIndex)) {
                 setFields(prev => {
                    const newFields = [...prev];
                    const [movedField] = newFields.splice(draggedIndex, 1);
                    newFields.push(movedField);
                    return newFields;
                });
             }
        }
    };

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white overflow-hidden">
            {/* Sidebar */}
            <div className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col flex-shrink-0 z-20">
                <div className="p-4 border-b border-slate-800">
                    <button onClick={onBack} className="flex items-center text-xs font-medium text-slate-400 hover:text-white transition-colors mb-4 bg-slate-800 px-3 py-1.5 rounded-md w-fit">
                        <IconArrowLeft className="w-3 h-3 mr-1" />
                        Back to Contact List
                    </button>
                    <div className="flex items-center justify-between text-white font-semibold">
                        <span>New Fields</span>
                        <IconChevronDown className="w-4 h-4 text-slate-400" />
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                    <div className="grid grid-cols-2 gap-2">
                        <SidebarItem label="Single Line" type="text" />
                        <SidebarItem label="Phone" type="tel" />
                        <SidebarItem label="Email" type="email" />
                        <SidebarItem label="Date" type="date" />
                        <SidebarItem label="Number" type="number" />
                        <SidebarItem label="Pick List" type="select" />
                        <SidebarItem label="Checkbox" type="checkbox" />
                        <SidebarItem label="URL" type="url" />
                    </div>

                    <div className="mt-6">
                        <div className="flex items-center justify-center p-3 border-2 border-dashed border-slate-700 rounded-lg text-slate-400 hover:text-white hover:border-slate-500 cursor-pointer transition-colors">
                            <span className="text-sm font-medium uppercase tracking-wide">New Section</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col min-w-0 bg-slate-100 dark:bg-slate-950">
                {/* Header */}
                <div className="h-16 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 px-6 flex justify-between items-center flex-shrink-0">
                    <div className="flex items-center">
                        <h1 className="text-lg font-bold text-slate-800 dark:text-white mr-2">Contact Layout</h1>
                        <span className="text-slate-400 mx-2">/</span>
                        <span className="text-slate-600 dark:text-slate-300 font-medium mr-2">Standard</span>
                    </div>
                    <div className="flex items-center space-x-3">
                         <button onClick={onBack} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                           Cancel
                         </button>
                         <button onClick={handleSaveLayout} className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded hover:bg-blue-500 transition-colors shadow-sm">
                           Save Layout
                         </button>
                    </div>
                </div>

                {/* Form Editor Canvas */}
                <div className="flex-1 overflow-y-auto p-8">
                    <div className="max-w-5xl mx-auto bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 min-h-[800px]">
                        <div className="p-8">
                             <div className="flex items-center mb-8">
                                <span className="text-sm font-bold text-slate-700 dark:text-slate-300 mr-3">Contact Image</span>
                                <IconToggleLeft className="w-8 h-8 text-emerald-500 cursor-pointer" />
                                <div className="ml-4 w-12 h-12 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center border border-slate-200 dark:border-slate-700">
                                    <IconUser className="w-6 h-6 text-slate-400" />
                                </div>
                             </div>

                             <div 
                                className="border border-dashed border-slate-300 dark:border-slate-700 rounded-lg p-1 bg-slate-50/50 dark:bg-slate-900/50 min-h-[400px] transition-colors"
                                onDragOver={handleContainerDragOver}
                                onDrop={handleDropContainer}
                             >
                                 <div className="flex justify-between items-center px-3 py-2 bg-slate-100 dark:bg-slate-800 rounded mb-4 cursor-move">
                                     <h3 className="font-bold text-slate-800 dark:text-slate-200">Contact Information</h3>
                                     <div className="flex items-center space-x-2">
                                         <IconSettings className="w-4 h-4 text-slate-400 cursor-pointer" />
                                         <IconPlus className="w-4 h-4 text-slate-400 cursor-pointer" />
                                     </div>
                                 </div>

                                 <div className="grid grid-cols-2 gap-x-8 gap-y-4 px-2 pb-2">
                                     {fields.map((field, index) => (
                                         <div 
                                            key={field.id}
                                            draggable={!field.isLocked}
                                            onDragStart={(e) => handleDragStart(e, index)}
                                            onDragOver={(e) => handleDragOver(e, index)}
                                            onDrop={(e) => handleDrop(e, index)}
                                            className={`relative transition-all duration-200 ${dragOverIndex === index ? 'border-t-2 border-blue-500 pt-2' : ''}`}
                                         >
                                             <div 
                                                className={`relative p-3 border rounded-md group cursor-pointer transition-colors
                                                    ${activeFieldId === field.id ? 'bg-purple-50 border-purple-300 dark:bg-purple-900/20 dark:border-purple-500/50' : 'bg-white border-slate-200 dark:bg-slate-800 dark:border-slate-700 hover:border-purple-300 dark:hover:border-purple-500/50'}
                                                `}
                                                onClick={(e) => handleFieldClick(e, field.id)}
                                             >
                                                <div className="flex justify-between items-start mb-1 pointer-events-none">
                                                    <div className="flex items-center">
                                                        {field.required && <div className="w-1 h-4 bg-red-500 mr-2 rounded-full" title="Required"></div>}
                                                        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{field.label}</span>
                                                    </div>
                                                    <button className="opacity-0 group-hover:opacity-100 text-slate-400">
                                                        <IconSettings className="w-3 h-3" />
                                                    </button>
                                                </div>

                                                <div className="flex items-center justify-between pointer-events-none">
                                                    {field.isComposite ? (
                                                        <div className="flex gap-2 w-full">
                                                            <div className="w-1/3 border-r border-slate-200 dark:border-slate-600 pr-2">
                                                                <span className="text-xs text-slate-400">Salutation</span>
                                                            </div>
                                                            <div className="flex-1">
                                                                <span className="text-sm text-blue-600 dark:text-blue-400">{field.value}</span>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <>
                                                            <span className={`text-sm ${field.value ? 'text-blue-600 dark:text-blue-400' : 'text-slate-400'}`}>
                                                                {field.value || field.type}
                                                            </span>
                                                            {field.isLocked && <span className="text-xs text-slate-400">🔒</span>}
                                                        </>
                                                    )}
                                                </div>

                                                {/* Context Menu */}
                                                {activeFieldId === field.id && (
                                                    <div className="absolute top-full left-0 mt-1 w-48 bg-white dark:bg-slate-800 rounded-lg shadow-xl border border-slate-200 dark:border-slate-700 z-50 overflow-hidden animate-fade-in-down cursor-default">
                                                        <div className="py-1">
                                                            <button 
                                                                onClick={(e) => { e.stopPropagation(); handleToggleRequired(field.id); }}
                                                                className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center"
                                                            >
                                                                <IconCheckSquare className={`w-3 h-3 mr-2 ${field.required ? 'text-purple-500' : 'text-slate-400'}`} />
                                                                {field.required ? 'Unmark Required' : 'Mark as Required'}
                                                            </button>
                                                            {!field.isLocked && (
                                                                <>
                                                                    <div className="border-t border-slate-200 dark:border-slate-700 my-1"></div>
                                                                    <button 
                                                                        onClick={(e) => { e.stopPropagation(); handleRemoveField(field.id); }}
                                                                        className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center"
                                                                    >
                                                                        <IconTrash className="w-3 h-3 mr-2" />
                                                                        Remove Field
                                                                    </button>
                                                                </>
                                                            )}
                                                        </div>
                                                    </div>
                                                )}
                                             </div>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ContactLayoutEditor;

import React, { useState } from 'react';
import { Contact, ContactStatus, LayoutField } from '../types';
import { IconFilter, IconPhone, IconMail, IconX, IconUser, IconBuilding, IconList, IconKanban, IconInfo } from './Icons';
import ContactLayoutEditor from './ContactLayoutEditor';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const DEFAULT_LAYOUT: LayoutField[] = [
    { id: 'f1', label: 'Contact Owner', type: 'User', key: 'owner', value: 'User', required: false, isLocked: true },
    { id: 'f2', label: 'Lead Source', type: 'select', key: 'leadSource', value: 'Option 1', required: false, isLocked: false },
    { id: 'f3', label: 'First Name', type: 'text', key: 'firstName', value: 'Mr. ', required: false, isLocked: false, isComposite: true },
    { id: 'f4', label: 'Last Name', type: 'text', key: 'lastName', value: 'Single Line', required: true, isLocked: false },
    { id: 'f5', label: 'Account Name', type: 'text', key: 'company', value: 'Lookup', required: true, isLocked: false },
    { id: 'f6', label: 'Title', type: 'text', key: 'title', value: 'Single Line', required: false, isLocked: false },
    { id: 'f7', label: 'Email', type: 'email', key: 'email', value: 'Email', required: false, isLocked: false },
    { id: 'f8', label: 'Department', type: 'text', key: 'department', value: 'Single Line', required: false, isLocked: false },
    { id: 'f9', label: 'Phone', type: 'tel', key: 'phone', value: 'Phone', required: false, isLocked: false },
    { id: 'f10', label: 'Home Phone', type: 'tel', key: 'homePhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f11', label: 'Other Phone', type: 'tel', key: 'otherPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f12', label: 'Fax', type: 'tel', key: 'fax', value: 'Phone', required: false, isLocked: false },
    { id: 'f13', label: 'Mobile', type: 'tel', key: 'mobile', value: 'Phone', required: false, isLocked: false },
    { id: 'f14', label: 'Date of Birth', type: 'date', key: 'dateOfBirth', value: 'Date', required: false, isLocked: false },
    { id: 'f15', label: 'Assistant', type: 'text', key: 'assistant', value: 'Single Line', required: false, isLocked: false },
    { id: 'f16', label: 'Asst Phone', type: 'tel', key: 'asstPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f17', label: 'Email Opt Out', type: 'checkbox', key: 'emailOptOut', value: 'Check', required: false, isLocked: false },
    { id: 'f18', label: 'Status', type: 'select', key: 'status', value: 'New', required: true, isLocked: false }
];

const CONTACT_STATUSES: ContactStatus[] = ['New', 'Active', 'Inactive'];

const LEAD_SOURCES = [
    'Advertisement',
    'Cold Call',
    'Employee Referral',
    'External Referral',
    'Online Store',
    'Partner',
    'Trade Show',
    'Web Download',
    'Web Search',
    'Chat'
];

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [layoutFields, setLayoutFields] = useState<LayoutField[]>(DEFAULT_LAYOUT);
  const [formData, setFormData] = useState<Partial<Contact>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);
  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor 
      currentLayout={layoutFields}
      onSave={(newLayout) => {
        setLayoutFields(newLayout);
        setIsLayoutEditorOpen(false);
      }}
      onBack={() => setIsLayoutEditorOpen(false)} 
    />;
  }

  const handleOpenModal = () => {
    setFormData({ status: 'New' }); // Default Values
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    setFormData({ ...contact });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    // Dynamic Validation based on Layout
    const missingFields = layoutFields.filter(field => field.required && !formData[field.key as keyof Contact] && field.key !== 'owner');

    if (missingFields.length > 0) {
      alert(`Please fill in the required fields: ${missingFields.map(f => f.label).join(', ')}`);
      return false;
    }

    // Name Construction logic
    let fullName = formData.name;
    if (!fullName) {
        const firstName = formData.firstName || '';
        const lastName = formData.lastName || '';
        fullName = `${firstName} ${lastName}`.trim();
        if (!fullName && formData.company) fullName = formData.company; // Fallback
    }

    const contactData = {
      ...formData,
      name: fullName || 'Unknown',
      status: formData.status || 'New',
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData({ status: 'New' });
      setEditingId(null);
    }
  };

  // Drag and Drop Handlers (Kanban)
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedContactId(id);
    e.dataTransfer.setData('contactId', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === id);

    if (contact && contact.status !== status) {
      onUpdateContact({ ...contact, status });
    }
    setDraggedContactId(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active': return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-300 dark:border-emerald-800';
      case 'Inactive': return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700';
      default: return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800';
    }
  };

  const renderField = (field: LayoutField) => {
      const isRequired = field.required;
      const commonClasses = `w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border ${isRequired && !formData[field.key as keyof Contact] ? 'border-red-300 dark:border-red-800' : 'border-slate-200 dark:border-slate-700'} rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white`;

      if (field.key === 'owner') {
          return (
            <div className="relative">
                <input type="text" value="Bayas Ahamed" readOnly className={`${commonClasses} cursor-default`} />
                <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            </div>
          );
      }

      if (field.isComposite && field.key === 'firstName') {
          return (
            <div className="flex gap-2">
                <select className="w-24 px-2 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:ring-1 focus:ring-blue-500 text-slate-900 dark:text-white text-sm">
                    <option>Mr.</option>
                    <option>Ms.</option>
                    <option>Dr.</option>
                </select>
                <input 
                    type="text" 
                    name={field.key} 
                    value={formData[field.key as keyof Contact] || ''} 
                    onChange={handleInputChange} 
                    className={commonClasses} 
                />
            </div>
          );
      }

      switch (field.type) {
          case 'select':
              let options = (
                 <>
                    <option value="">-None-</option>
                    <option value="Option 1">Option 1</option>
                    <option value="Option 2">Option 2</option>
                 </>
              );

              if (field.key === 'status') {
                  options = <>{CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}</>;
              } else if (field.key === 'leadSource') {
                  options = (
                    <>
                        <option value="">-None-</option>
                        {LEAD_SOURCES.map(s => <option key={s} value={s}>{s}</option>)}
                    </>
                  );
              }

              return (
                  <select name={field.key} value={formData[field.key as keyof Contact] || ''} onChange={handleInputChange} className={commonClasses}>
                      {options}
                  </select>
              );
          case 'checkbox':
              return (
                  <div className="flex items-center h-full">
                      <input type="checkbox" name={field.key} checked={!!formData[field.key as keyof Contact]} onChange={handleInputChange} className="w-4 h-4 text-blue-600 bg-slate-100 border-slate-300 rounded focus:ring-blue-500 dark:focus:ring-blue-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600" />
                  </div>
              );
          default:
              return (
                  <div className="relative">
                    <input 
                        type={field.type} 
                        name={field.key} 
                        value={formData[field.key as keyof Contact] || ''} 
                        onChange={handleInputChange} 
                        className={commonClasses} 
                    />
                    {field.key === 'company' && <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />}
                  </div>
              );
      }
  };

  return (
    <>
      <div className="space-y-6 h-full flex flex-col">
        {/* Header and Kanban/List Toggle - Same as before */}
        <div className="flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
             <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Contacts</h1>
             <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700">
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}><IconList className="w-4 h-4" /></button>
                <button onClick={() => setViewMode('kanban')} className={`p-1.5 rounded-md transition-all ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}><IconKanban className="w-4 h-4" /></button>
             </div>
          </div>
          <button onClick={handleOpenModal} className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all">+ New Contact</button>
        </div>

        {/* Views Render (List or Kanban) - Same as before */}
        {viewMode === 'list' ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <div className="flex items-center space-x-2"><IconFilter className="w-4 h-4 text-slate-400" /><select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none"><option>All Contacts</option></select></div>
            </div>
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                  <th className="px-6 py-4 font-medium">Name</th>
                  <th className="px-6 py-4 font-medium">Title</th>
                  <th className="px-6 py-4 font-medium">Account Name</th>
                  <th className="px-6 py-4 font-medium">Email</th>
                  <th className="px-6 py-4 font-medium">Phone</th>
                  <th className="px-6 py-4 font-medium">Status</th>
                  <th className="px-6 py-4 font-medium">Last Activity</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                {contacts.map((contact) => (
                  <tr key={contact.id} onClick={() => handleEditClick(contact)} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer">
                    <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center"><div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center mr-3 text-sm font-bold text-slate-600 dark:text-slate-300">{contact.name.charAt(0)}</div>{contact.name}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.title}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.company}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300 flex items-center"><IconMail className="w-3 h-3 mr-1.5 opacity-50" />{contact.email}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300"><div className="flex items-center"><IconPhone className="w-3 h-3 mr-1.5 opacity-50" />{contact.phone}</div></td>
                    <td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-semibold rounded-full border ${getStatusColor(contact.status || 'New')}`}>{contact.status || 'New'}</span></td>
                    <td className="px-6 py-4 text-slate-500 dark:text-slate-400">{contact.lastActivity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
            <div className="flex h-full gap-6 min-w-full">
              {CONTACT_STATUSES.map(status => (
                <div key={status} onDragOver={handleDragOver} onDrop={(e) => handleDrop(e, status)} className="flex-1 min-w-[320px] flex flex-col bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl h-full">
                  <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-white/50 dark:bg-slate-800/50 rounded-t-xl backdrop-blur-sm sticky top-0 z-10">
                    <h3 className="font-semibold text-slate-700 dark:text-slate-200 flex items-center gap-2"><span className={`w-2.5 h-2.5 rounded-full ${status === 'Active' ? 'bg-emerald-500' : status === 'Inactive' ? 'bg-slate-400' : 'bg-blue-500'}`}></span>{status}</h3>
                    <span className="bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold px-2 py-0.5 rounded-full">{contacts.filter(c => (c.status || 'New') === status).length}</span>
                  </div>
                  <div className="p-4 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                     {contacts.filter(c => (c.status || 'New') === status).map(contact => (
                       <div key={contact.id} draggable onDragStart={(e) => handleDragStart(e, contact.id)} onClick={() => handleEditClick(contact)} className={`p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm hover:shadow-md transition-all cursor-move group select-none ${draggedContactId === contact.id ? 'opacity-50 border-dashed border-slate-400' : 'hover:border-purple-400 dark:hover:border-purple-500/50'}`}>
                         <div className="flex items-start justify-between mb-2">
                           <div className="flex items-center"><div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 mr-2 border border-slate-200 dark:border-slate-600">{contact.name.charAt(0)}</div><div><h4 className="font-semibold text-slate-800 dark:text-slate-100 text-sm">{contact.name}</h4><p className="text-xs text-slate-500 dark:text-slate-400">{contact.title}</p></div></div>
                         </div>
                         <div className="mb-3 pl-10"><p className="text-sm text-slate-600 dark:text-slate-300 flex items-center mb-1"><IconBuilding className="w-3 h-3 mr-1.5 text-slate-400" />{contact.company}</p>{(contact.email || contact.phone) && (<div className="flex items-center gap-3 text-xs text-slate-500 dark:text-slate-400 mt-2">{contact.email && <span className="flex items-center gap-1"><IconMail className="w-3 h-3" /> Email</span>}{contact.phone && <span className="flex items-center gap-1"><IconPhone className="w-3 h-3" /> Call</span>}</div>)}</div>
                         <div className="flex justify-between items-center pt-2 border-t border-slate-100 dark:border-slate-700/50 pl-10"><span className="text-xs text-slate-400">{contact.lastActivity}</span></div>
                       </div>
                     ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-5xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            {/* Header */}
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50">
               <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                    {editingId ? 'Edit Contact' : 'Create Contact'}
                  </h2>
                  <button onClick={handleEditPageLayout} className="text-sm text-blue-600 hover:underline">Edit Page Layout</button>
               </div>
               <div className="flex items-center gap-2">
                 <button onClick={handleCloseModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                 <button onClick={handleSaveAndNew} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Save and New</button>
                 <button onClick={handleSubmit} className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded hover:bg-blue-500 transition-colors shadow-sm">Save</button>
               </div>
            </div>

            {/* Dynamic Form Content */}
            <div className="overflow-y-auto p-6 md:p-8 bg-white dark:bg-slate-900">
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                    {layoutFields.map((field) => (
                        <div key={field.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                            <label className={`text-sm text-slate-600 dark:text-slate-400 md:text-right ${field.required ? 'border-l-2 border-red-500 pl-2 md:border-l-0 md:pl-0 md:after:content-["*"] md:after:text-red-500 md:after:ml-1' : ''}`}>
                                {field.label}
                            </label>
                            <div className="md:col-span-2">
                                {renderField(field)}
                            </div>
                        </div>
                    ))}
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Contacts;

import React, { useState } from 'react';
import { LayoutField } from '../types';
import { 
    IconArrowLeft, 
    IconSettings, 
    IconGripVertical, 
    IconChevronDown, 
    IconChevronRight, 
    IconUser, 
    IconToggleLeft, 
    IconPlus, 
    IconTrash, 
    IconCheckSquare
} from './Icons';

interface ContactLayoutEditorProps {
    currentLayout: LayoutField[];
    onSave: (layout: LayoutField[]) => void;
    onBack: () => void;
}

const SidebarItem = ({ label, type }: { label: string, type: string }) => {
    const handleDragStart = (e: React.DragEvent) => {
        // Create a template for the new field. 
        const fieldKey = `custom_${type.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${Date.now()}`;
        const newFieldData: LayoutField = {
            id: `new_template_${Date.now()}`, 
            label: label,
            type: type,
            key: fieldKey,
            required: false,
            isLocked: false,
            value: `[${label}]`
        };
        e.dataTransfer.setData('application/new-field', JSON.stringify(newFieldData));
        e.dataTransfer.effectAllowed = 'copy';
    };

    return (
        <div 
            draggable 
            onDragStart={handleDragStart}
            className="flex items-center px-3 py-2 bg-slate-800 border border-slate-700 rounded mb-2 cursor-grab hover:bg-slate-700 transition-colors active:cursor-grabbing"
        >
            <IconGripVertical className="w-4 h-4 text-slate-500 mr-2" />
            <span className="text-sm text-slate-300">{label}</span>
        </div>
    );
};

const ContactLayoutEditor: React.FC<ContactLayoutEditorProps> = ({ currentLayout, onSave, onBack }) => {
    const [fields, setFields] = useState<LayoutField[]>(currentLayout);
    const [activeFieldId, setActiveFieldId] = useState<string | null>(null);
    const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
    const [isDraggingOverContainer, setIsDraggingOverContainer] = useState(false);

    // Close context menu when clicking outside
    React.useEffect(() => {
        const handleClickOutside = () => setActiveFieldId(null);
        window.addEventListener('click', handleClickOutside);
        return () => window.removeEventListener('click', handleClickOutside);
    }, []);

    const handleFieldClick = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        setActiveFieldId(activeFieldId === id ? null : id);
    };

    const handleRemoveField = (id: string) => {
        setFields(prev => prev.filter(f => f.id !== id));
        setActiveFieldId(null);
    };

    const handleToggleRequired = (id: string) => {
        setFields(prev => prev.map(f => f.id === id ? { ...f, required: !f.required } : f));
        setActiveFieldId(null);
    };

    const handleSaveLayout = () => {
        onSave(fields);
    };

    // Helper to check for type existence in DataTransferItemList or array
    const hasType = (types: any, type: string) => {
        if (!types) return false;
        if (types.includes) return types.includes(type);
        if (types.contains) return types.contains(type); // For DOMStringList
        for (let i = 0; i < types.length; i++) {
            if (types[i] === type) return true;
        }
        return false;
    };

    // Drag and Drop Handlers
    const handleDragStart = (e: React.DragEvent, index: number) => {
        e.dataTransfer.setData('application/field-index', index.toString());
        e.dataTransfer.effectAllowed = 'move';
        setActiveFieldId(null);
    };

    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault(); 
        e.stopPropagation();

        if (hasType(e.dataTransfer.types, 'application/new-field')) {
            e.dataTransfer.dropEffect = 'copy';
        } else {
            e.dataTransfer.dropEffect = 'move';
        }

        setDragOverIndex(index);
        setIsDraggingOverContainer(true);
    };

    const handleContainerDragOver = (e: React.DragEvent) => {
        e.preventDefault();

        if (hasType(e.dataTransfer.types, 'application/new-field')) {
            e.dataTransfer.dropEffect = 'copy';
        } else {
            e.dataTransfer.dropEffect = 'move';
        }

        setIsDraggingOverContainer(true);
    };

    const handleContainerDragLeave = (e: React.DragEvent) => {
        // Only clear if leaving the main container, not entering a child
        if (e.currentTarget.contains(e.relatedTarget as Node)) return;
        setIsDraggingOverContainer(false);
        setDragOverIndex(null);
    };

    // Helper to create a unique field from template
    const createFieldFromTemplate = (template: LayoutField): LayoutField => {
        const timestamp = Date.now();
        const randomStr = Math.random().toString(36).substring(2, 9);
        return {
            ...template,
            id: `field_${timestamp}_${randomStr}`,
            key: `custom_${template.type}_${timestamp}_${randomStr}`,
        };
    };

    const handleDrop = (e: React.DragEvent, dropIndex: number) => {
        e.preventDefault();
        e.stopPropagation();
        setDragOverIndex(null);
        setIsDraggingOverContainer(false);

        const newFieldJson = e.dataTransfer.getData('application/new-field');
        const draggedIndexStr = e.dataTransfer.getData('application/field-index');

        if (newFieldJson) {
            // Adding a new field from sidebar
            try {
                const template = JSON.parse(newFieldJson) as LayoutField;
                const newField = createFieldFromTemplate(template);

                setFields(prev => {
                    const newFields = [...prev];
                    newFields.splice(dropIndex, 0, newField);
                    return newFields;
                });
            } catch (err) {
                console.error("Error parsing new field data:", err);
            }
        } else if (draggedIndexStr) {
            // Reordering existing field
            const draggedIndex = parseInt(draggedIndexStr, 10);
            if (!isNaN(draggedIndex) && draggedIndex !== dropIndex) {
                setFields(prev => {
                    const newFields = [...prev];
                    const [movedField] = newFields.splice(draggedIndex, 1);
                    // Adjust drop index if dragging from above
                    const adjustedDropIndex = draggedIndex < dropIndex ? dropIndex - 1 : dropIndex;
                    newFields.splice(adjustedDropIndex, 0, movedField);
                    return newFields;
                });
            }
        }
    };

    const handleDropContainer = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDraggingOverContainer(false);
        setDragOverIndex(null);

        // If dropping directly on container (not on a specific item), we append to the end.
        // Or if it bubbled up (though we stop propagation in handleDrop item, so this catches drops on empty space)

        const newFieldJson = e.dataTransfer.getData('application/new-field');
        const draggedIndexStr = e.dataTransfer.getData('application/field-index');

        if (newFieldJson) {
             try {
                const template = JSON.parse(newFieldJson) as LayoutField;
                const newField = createFieldFromTemplate(template);
                setFields(prev => [...prev, newField]);
             } catch (err) {
                 console.error("Error parsing new field data:", err);
             }
        } else if (draggedIndexStr) {
             // If dragging an existing field to the container background (effectively moving to end)
             const draggedIndex = parseInt(draggedIndexStr, 10);
             if (!isNaN(draggedIndex)) {
                 setFields(prev => {
                    const newFields = [...prev];
                    const [movedField] = newFields.splice(draggedIndex, 1);
                    newFields.push(movedField);
                    return newFields;
                });
             }
        }
    };

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white overflow-hidden">
            {/* Sidebar */}
            <div className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col flex-shrink-0 z-20">
                <div className="p-4 border-b border-slate-800">
                    <button onClick={onBack} className="flex items-center text-xs font-medium text-slate-400 hover:text-white transition-colors mb-4 bg-slate-800 px-3 py-1.5 rounded-md w-fit">
                        <IconArrowLeft className="w-3 h-3 mr-1" />
                        Back to Contact List
                    </button>
                    <div className="flex items-center justify-between text-white font-semibold">
                        <span>New Fields</span>
                        <IconChevronDown className="w-4 h-4 text-slate-400" />
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                    <div className="grid grid-cols-2 gap-2">
                        <SidebarItem label="Single Line" type="text" />
                        <SidebarItem label="Phone" type="tel" />
                        <SidebarItem label="Email" type="email" />
                        <SidebarItem label="Date" type="date" />
                        <SidebarItem label="Number" type="number" />
                        <SidebarItem label="Pick List" type="select" />
                        <SidebarItem label="Checkbox" type="checkbox" />
                        <SidebarItem label="URL" type="url" />
                    </div>

                    <div className="mt-6">
                        <div className="flex items-center justify-center p-3 border-2 border-dashed border-slate-700 rounded-lg text-slate-400 hover:text-white hover:border-slate-500 cursor-pointer transition-colors">
                            <span className="text-sm font-medium uppercase tracking-wide">New Section</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col min-w-0 bg-slate-100 dark:bg-slate-950">
                {/* Header */}
                <div className="h-16 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 px-6 flex justify-between items-center flex-shrink-0">
                    <div className="flex items-center">
                        <h1 className="text-lg font-bold text-slate-800 dark:text-white mr-2">Contact Layout</h1>
                        <span className="text-slate-400 mx-2">/</span>
                        <span className="text-slate-600 dark:text-slate-300 font-medium mr-2">Standard</span>
                    </div>
                    <div className="flex items-center space-x-3">
                         <button onClick={onBack} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                           Cancel
                         </button>
                         <button onClick={handleSaveLayout} className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded hover:bg-blue-500 transition-colors shadow-sm">
                           Save Layout
                         </button>
                    </div>
                </div>

                {/* Form Editor Canvas */}
                <div className="flex-1 overflow-y-auto p-8">
                    <div className="max-w-5xl mx-auto bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 min-h-[800px]">
                        <div className="p-8">
                             <div className="flex items-center mb-8">
                                <span className="text-sm font-bold text-slate-700 dark:text-slate-300 mr-3">Contact Image</span>
                                <IconToggleLeft className="w-8 h-8 text-emerald-500 cursor-pointer" />
                                <div className="ml-4 w-12 h-12 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center border border-slate-200 dark:border-slate-700">
                                    <IconUser className="w-6 h-6 text-slate-400" />
                                </div>
                             </div>

                             <div 
                                className={`border-2 rounded-lg p-1 min-h-[400px] transition-all duration-200 
                                    ${isDraggingOverContainer 
                                        ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/10 dark:border-blue-500' 
                                        : 'border-dashed border-slate-300 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/50'
                                    }`}
                                onDragOver={handleContainerDragOver}
                                onDragLeave={handleContainerDragLeave}
                                onDrop={handleDropContainer}
                             >
                                 <div className="flex justify-between items-center px-3 py-2 bg-slate-100 dark:bg-slate-800 rounded mb-4 cursor-move">
                                     <h3 className="font-bold text-slate-800 dark:text-slate-200">Contact Information</h3>
                                     <div className="flex items-center space-x-2">
                                         <IconSettings className="w-4 h-4 text-slate-400 cursor-pointer" />
                                         <IconPlus className="w-4 h-4 text-slate-400 cursor-pointer" />
                                     </div>
                                 </div>

                                 <div className="grid grid-cols-2 gap-x-8 gap-y-4 px-2 pb-2">
                                     {fields.map((field, index) => (
                                         <div 
                                            key={field.id}
                                            draggable={!field.isLocked}
                                            onDragStart={(e) => handleDragStart(e, index)}
                                            onDragOver={(e) => handleDragOver(e, index)}
                                            onDrop={(e) => handleDrop(e, index)}
                                            className={`relative transition-all duration-200 ${dragOverIndex === index ? 'pt-8' : ''}`}
                                         >
                                             {dragOverIndex === index && (
                                                <div className="absolute top-0 left-0 right-0 h-6 bg-blue-100 dark:bg-blue-900/30 border border-blue-300 dark:border-blue-500 rounded-sm flex items-center justify-center mb-2">
                                                    <span className="text-xs text-blue-600 dark:text-blue-400 font-medium">Insert Here</span>
                                                </div>
                                             )}

                                             <div 
                                                className={`relative p-3 border rounded-md group cursor-pointer transition-colors
                                                    ${activeFieldId === field.id ? 'bg-purple-50 border-purple-300 dark:bg-purple-900/20 dark:border-purple-500/50' : 'bg-white border-slate-200 dark:bg-slate-800 dark:border-slate-700 hover:border-purple-300 dark:hover:border-purple-500/50'}
                                                `}
                                                onClick={(e) => handleFieldClick(e, field.id)}
                                             >
                                                <div className="flex justify-between items-start mb-1 pointer-events-none">
                                                    <div className="flex items-center">
                                                        {field.required && <div className="w-1 h-4 bg-red-500 mr-2 rounded-full" title="Required"></div>}
                                                        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{field.label}</span>
                                                    </div>
                                                    <button className="opacity-0 group-hover:opacity-100 text-slate-400">
                                                        <IconSettings className="w-3 h-3" />
                                                    </button>
                                                </div>

                                                <div className="flex items-center justify-between pointer-events-none">
                                                    {field.isComposite ? (
                                                        <div className="flex gap-2 w-full">
                                                            <div className="w-1/3 border-r border-slate-200 dark:border-slate-600 pr-2">
                                                                <span className="text-xs text-slate-400">Salutation</span>
                                                            </div>
                                                            <div className="flex-1">
                                                                <span className="text-sm text-blue-600 dark:text-blue-400">{field.value}</span>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <>
                                                            <span className={`text-sm ${field.value ? 'text-blue-600 dark:text-blue-400' : 'text-slate-400'}`}>
                                                                {field.value || field.type}
                                                            </span>
                                                            {field.isLocked && <span className="text-xs text-slate-400">🔒</span>}
                                                        </>
                                                    )}
                                                </div>

                                                {/* Context Menu */}
                                                {activeFieldId === field.id && (
                                                    <div className="absolute top-full left-0 mt-1 w-48 bg-white dark:bg-slate-800 rounded-lg shadow-xl border border-slate-200 dark:border-slate-700 z-50 overflow-hidden animate-fade-in-down cursor-default">
                                                        <div className="py-1">
                                                            <button 
                                                                onClick={(e) => { e.stopPropagation(); handleToggleRequired(field.id); }}
                                                                className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center"
                                                            >
                                                                <IconCheckSquare className={`w-3 h-3 mr-2 ${field.required ? 'text-purple-500' : 'text-slate-400'}`} />
                                                                {field.required ? 'Unmark Required' : 'Mark as Required'}
                                                            </button>
                                                            {!field.isLocked && (
                                                                <>
                                                                    <div className="border-t border-slate-200 dark:border-slate-700 my-1"></div>
                                                                    <button 
                                                                        onClick={(e) => { e.stopPropagation(); handleRemoveField(field.id); }}
                                                                        className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center"
                                                                    >
                                                                        <IconTrash className="w-3 h-3 mr-2" />
                                                                        Remove Field
                                                                    </button>
                                                                </>
                                                            )}
                                                        </div>
                                                    </div>
                                                )}
                                             </div>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ContactLayoutEditor;

import React, { useState, useMemo } from 'react';
import { Contact, ContactStatus, LayoutField } from '../types';
import { IconFilter, IconPhone, IconMail, IconX, IconUser, IconBuilding, IconList, IconKanban, IconInfo } from './Icons';
import ContactLayoutEditor from './ContactLayoutEditor';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const DEFAULT_LAYOUT: LayoutField[] = [
    { id: 'f1', label: 'Contact Owner', type: 'User', key: 'owner', value: 'User', required: false, isLocked: true },
    { id: 'f2', label: 'Lead Source', type: 'select', key: 'leadSource', value: 'Option 1', required: false, isLocked: false },
    { id: 'f3', label: 'First Name', type: 'text', key: 'firstName', value: 'Mr. ', required: false, isLocked: false, isComposite: true },
    { id: 'f4', label: 'Last Name', type: 'text', key: 'lastName', value: 'Single Line', required: true, isLocked: false },
    { id: 'f5', label: 'Account Name', type: 'text', key: 'company', value: 'Lookup', required: true, isLocked: false },
    { id: 'f6', label: 'Title', type: 'text', key: 'title', value: 'Single Line', required: false, isLocked: false },
    { id: 'f7', label: 'Email', type: 'email', key: 'email', value: 'Email', required: false, isLocked: false },
    { id: 'f8', label: 'Department', type: 'text', key: 'department', value: 'Single Line', required: false, isLocked: false },
