    { id: 'f10', label: 'Home Phone', type: 'tel', key: 'homePhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f11', label: 'Other Phone', type: 'tel', key: 'otherPhone', value: 'Phone', required: false, isLocked: false },
